const mainKeyboard = {
  inline_keyboard: [
    [{ text: '📖 Каталог ароматов', callback_data: 'catalog' }],
    [{ text: '✨ Подобрать', callback_data: 'pick' }],
    [{ text: '🎓 Инфо', callback_data: 'info' }],
  ],
};

const catalogKeyboard = {
  inline_keyboard: [
    [{ text: '🌸 Цветочные', callback_data: 'category:flowers' }],
    [{ text: '🌲 Древесные', callback_data: 'category:wood' }],
    [{ text: '🌙 Восточные', callback_data: 'category:oriental' }],
    [{ text: '🍋 Цитрусовые', callback_data: 'category:citrus' }],
    [{ text: '⬅️ Назад', callback_data: 'back' }],
  ],
};

return $input.all().map((item) => {
  const update = item.json.body ?? item.json;
  const message = update.message ?? null;
  const callbackQuery = update.callback_query ?? null;

  const chatId = message?.chat?.id ?? callbackQuery?.message?.chat?.id ?? null;
  const userId = message?.from?.id ?? callbackQuery?.from?.id ?? null;
  const messageId = message?.message_id ?? callbackQuery?.message?.message_id ?? null;
  const callbackQueryId = callbackQuery?.id ?? null;
  const text = (message?.text ?? callbackQuery?.data ?? '').trim();

  const output = {
    chatId,
    userId,
    messageId,
    callbackQueryId,
    originalText: text,
    shouldCallAi: false,
    telegramMethod: '',
    telegramPayload: {},
    aiPrompt: '',
    routeType: 'telegram',
    categoryKey: '',
    airtableFormula: '',
  };

  if (!chatId) {
    return { json: output };
  }

  if (callbackQuery) {
    if (text === 'catalog') {
      output.telegramMethod = 'sendMessage';
      output.telegramPayload = {
        chat_id: chatId,
        text: '🌿 Выберите категорию аромата:',
        reply_markup: catalogKeyboard,
      };
      return { json: output };
    }

    if (text.startsWith('category:')) {
      const categoryKey = text.split(':')[1];
      output.routeType = 'airtable';
      output.telegramMethod = 'airtable_lookup';
      output.categoryKey = categoryKey;
      output.airtableFormula = `{category_key}='${categoryKey}'`;
      return { json: output };
    }

    if (text === 'pick') {
      output.shouldCallAi = true;
      output.routeType = 'ai';
      output.aiPrompt = 'Ты персональный парфюмерный консультант в Telegram. Отвечай по-русски, дружелюбно, коротко и по делу. Помогай подобрать аромат по вкусу, настроению, сезону, случаю и характеру человека. Если данных мало, задай 1-2 уточняющих вопроса. Пользователь нажал кнопку "Подобрать". Начни диалог с фразы: "С удовольствием помогу подобрать аромат. Расскажи, что тебе ближе: свежие, сладкие, древесные, цветочные, цитрусовые или восточные ароматы?"';
      return { json: output };
    }

    if (text === 'info') {
      output.telegramMethod = 'sendMessage';
      output.telegramPayload = {
        chat_id: chatId,
        text: 'Я могу показать категории ароматов, помочь с подбором и ответить на вопросы о парфюмерии.',
      };
      return { json: output };
    }

    if (text === 'back') {
      output.telegramMethod = 'sendPhoto';
      output.telegramPayload = {
        chat_id: chatId,
        photo: 'https://i.ibb.co/CKHw7tLj/photo-2026-03-05-22-07-48.jpg',
        caption: 'Привет! Я твой персональный парфюмерный гид. Помогу подобрать аромат под настроение или расширить твои знания о мире парфюма. С чего начнем?',
        reply_markup: mainKeyboard,
      };
      return { json: output };
    }
  }

  if (text === '/start') {
    output.telegramMethod = 'sendPhoto';
    output.telegramPayload = {
      chat_id: chatId,
      photo: 'https://i.ibb.co/CKHw7tLj/photo-2026-03-05-22-07-48.jpg',
      caption: 'Привет! Я твой персональный парфюмерный гид. Помогу подобрать аромат под настроение или расширить твои знания о мире парфюма. С чего начнем?',
      reply_markup: mainKeyboard,
    };
    return { json: output };
  }

  output.shouldCallAi = true;
  output.routeType = 'ai';
  output.aiPrompt = `Ты персональный парфюмерный Telegram-бот. Отвечай по-русски, дружелюбно, коротко и по делу. Если пользователь просит подбор аромата, помоги как консультант. Сообщение пользователя: ${text}`;

  return { json: output };
});

const items = $input.all();
const response = items[0].json;
const chatId = $('Code Router').first().json.chatId;

const reply = response.choices?.[0]?.message?.content || 'Нет ответа от AI';

return [{ json: { chatId, text: reply } }];

const items = $input.all();
const data = items[0].json;
const categoryKey = data.categoryKey;
const chatId = data.chatId;
const callbackQueryId = data.callbackQueryId;

const categoryNames = {
  flowers: '🌸 Цветочные ароматы',
  wood: '🌲 Древесные ароматы',
  oriental: '🌙 Восточные ароматы',
  citrus: '🍋 Цитрусовые ароматы',
};

const categoryDescriptions = {
  flowers: 'Розы, жасмин, ирис, пион, ландыш, тубероза — женственность и романтика.',
  wood: 'Сандал, кедр, ветивер, уд, пачули — тёплые, глубокие, уверенные.',
  oriental: 'Амбра, ваниль, мускус, специи, ладан — чувственность и загадка.',
  citrus: 'Бергамот, лимон, грейпфрут, мандарин, юзу — свежесть и энергия.',
};

const name = categoryNames[categoryKey] || categoryKey;
const desc = categoryDescriptions[categoryKey] || 'Описание скоро появится.';

const backKeyboard = {
  inline_keyboard: [
    [{ text: '⬅️ К категориям', callback_data: 'catalog' }],
    [{ text: '🏠 Главное меню', callback_data: 'back' }],
  ],
};

return [{
  json: {
    chatId,
    callbackQueryId,
    categoryKey,
    text: `${name}\n\n${desc}\n\n💡 Скоро здесь появятся конкретные ароматы из каталога. А пока — можешь нажать «✨ Подобрать» в главном меню, и я помогу выбрать аромат лично для тебя.`,
    reply_markup: backKeyboard,
  },
}];
